command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-resident-window --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "d395db0f40b2a3863be4216ba1644f46f42c8dc0") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-resident-window origin/work/large-folder-resident-window
if ($LASTEXITCODE -ne 0) { throw "checkout harness fix failed" }
if ((git rev-parse HEAD).Trim() -ne "1c5779448a8cb194ff1a506ccfdd7cf0239f8222") { throw "candidate mismatch" }
$changedProduct = git diff --name-only 37d4cc023777c67a963710efd2e17ee7125a7cae..HEAD -- app/winui src/base
if ($LASTEXITCODE -ne 0) { throw "product-diff check failed" }
if ($changedProduct) { throw "harness-only resume unexpectedly changes product files: $changedProduct" }
if (!(Test-Path -LiteralPath "out\winui\Release\flyExplorer.exe")) { throw "accepted candidate Release binary missing" }

python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 2300 --configuration Release --resident-window-evidence after
if ($LASTEXITCODE -ne 0) { throw "focused resident-window GUI/visual resume failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_RESIDENT_WINDOW_GUI_RESUME_PASS"
